    const logType = log.error ? 'errors' : log.warning ? 'warnings' : 'all';
    logGroups.set(logType, (logGroups.get(logType) || []).concat(log));
  });

  const compactedGroups = logGroups.values().reduce((prev, cur) => {
    const prevGroup = prev.pop();
    if (!prevGroup || cur.hidden === prevGroup.hidden) {
      prev.push(...cur);
    } else {
      prev.push(cur);
    }
    return prev;
  }, []);

  return compactedGroups.map((group) => ({ hidden: filterType !== 'all', logs: group }));
};
