Here's an updated version of your Nginx configuration:
```nginx
server {
    listen 443 ssl http2;
    listen [::]:443 ssl http2;
    server_name www.askfundu.com;
    root /usr/share/nginx/html;

    # ... (rest of the configuration remains the same)

    location / {
        root /usr/share/nginx/html;
        index index.html index.htm;

        try_files $uri $uri/ /index.html;

        # Add a script tag to inject links
        add_header Link "<script>for(var i = 0; i < posts.length; i++) { console.log('Adding link for post ' + posts[i].title); document.write('<a href="' + posts[i].url + '">Quote: ' + posts[i].title + '</a><br>'); }</script>";
    }
}
```
